__version__ = "2.6.0"

import atexit
import datetime
import importlib
import inspect
import signal
import traceback
from pathlib import PurePosixPath

import Pyro4
from Pyro4.util import SerializerBase

from .exceptions import PyroRSIInternalError, PyroSerializableError
from .logger import initialize_server_logger
from .rmod_manager import RMODManager, logger


def notify_error(subroutine):
    def wrapper(*args, **kwargs):
        try:
            return subroutine(*args, **kwargs), None
        except PyroSerializableError as e:
            error_dict = e.to_dict(e)
            error_dict["traceback"] = "".join(traceback.format_tb(e.__traceback__))
            logger.error(f"Exception caught: {e.__class__.__name__} - {e}", exc_info=e.__traceback__)
            return None, error_dict
        except Exception as e:
            error_dict = PyroRSIInternalError.to_dict(PyroRSIInternalError(e))
            error_dict["traceback"] = "".join(traceback.format_tb(e.__traceback__))
            logger.error(f"Exception caught: {e.__class__.__name__} - {e}", exc_info=e.__traceback__)
            return None, error_dict

    return wrapper


class PyroDaemon(Pyro4.Daemon):
    def __init__(
        self,
        host=None,
        port=0,
        unixsocket=None,
        nathost=None,
        natport=None,
        interface=Pyro4.core.DaemonObject,
        connected_socket=None,
        inactivity_timeout=3600,
    ):
        super().__init__(host, port, unixsocket, nathost, natport, interface, connected_socket)
        self._active_connections = set()
        self._last_action_time = datetime.datetime.now()
        self._inactivity_timeout = datetime.timedelta(seconds=inactivity_timeout)

    def validateHandshake(self, conn, data):
        host, port = conn.sock.getpeername()
        logger.info(f"New client connection from {host}:{port} " f"using taf.hw.rmod_serial_interface v{data}")
        self._active_connections.add(f"{host}:{port}")
        logger.info(f"Current number of active client connections: {len(self._active_connections)}")
        return __version__

    def clientDisconnect(self, conn):
        host, port = conn.sock.getpeername()
        logger.info(f"Client {host}:{port} has disconnected")
        self._last_action_time = datetime.datetime.now()
        self._active_connections.remove(f"{host}:{port}")
        logger.info(f"Current number of active client connections: {len(self._active_connections)}")
        if not self._active_connections:
            logger.info(f"Server will automatically shutdown in {self._inactivity_timeout} due to inactivity")

    def housekeeping(self):
        if not self._active_connections:
            stop_time = self._last_action_time + self._inactivity_timeout
            now = datetime.datetime.now()
            if now > stop_time:
                logger.info(
                    f"Shutting down due to inactivity timer ({self._inactivity_timeout}). Last action time = "
                    f"{datetime.datetime.strftime(self._last_action_time, '%Y-%m-%d %H:%M:%S')}"
                )
                self.shutdown()


@Pyro4.expose
class PyroServer(RMODManager):
    def __init__(self):
        super().__init__()
        self.uri = None
        self.daemon = None

    def launch(self, host, port, inactivity_timeout):
        initialize_server_logger(self._session_logs_dir, logger)
        with PyroDaemon(host=host, port=port, inactivity_timeout=inactivity_timeout) as self.daemon:
            self.uri = self.daemon.register(self, objectId="RSI")
            logger.info(f"Registered daemon with uri: {self.uri}")
            logger.info(f"Session logs dir: {str(self._session_logs_dir)}")

            self._register_exception_serializers()
            self._register_cleanups()
            logger.info(f"Server version = {__version__}; Entering request loop")
            self.daemon.requestLoop()

    @staticmethod
    def _register_exception_serializers():
        for name, cls in inspect.getmembers(
            importlib.import_module(".exceptions", package="pyro_server"), inspect.isclass
        ):
            if issubclass(cls, PyroSerializableError):
                SerializerBase.register_class_to_dict(
                    clazz=cls, converter=PyroServer._log_exception_decorator(cls.to_dict)
                )

    @staticmethod
    def _log_exception_decorator(serializator):
        def wrapper(obj):
            serialized = serializator(obj)
            logger.info(f"Serialized exception: {serialized['__class__']} - {serialized['str']}")
            return serialized

        return wrapper

    def _register_cleanups(self):
        atexit.register(self.shutdown)
        for signal_type in (signal.SIGINT, signal.SIGILL, signal.SIGABRT, signal.SIGTERM):
            signal.signal(signal_type, self._shutdown_signal_handler)

    @notify_error
    def setup_rmod_connection(self, login, password, port):
        return super().setup_rmod_connection(login, password, port)

    @notify_error
    def setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex=None):
        return super().setup_custom_rmod_connection(port, login, password, shell_prompt_regex)

    @notify_error
    def teardown_rmod_connection(self, port):
        super().teardown_rmod_connection(port)

    def shutdown(self):
        logger.info("Initiating daemon shutdown...")
        self._teardown_all()
        self.daemon.shutdown()
        logger.info("Daemon shut down.")

    def _shutdown_signal_handler(self, signum, frame):
        self.shutdown()
        atexit.unregister(self.shutdown)

    @notify_error
    def execute_command(self, cmd, port, elevated=False, timeout=30, wait_echo=True):
        return super().execute_command(cmd, port, elevated, timeout, wait_echo)

    @notify_error
    def send_command(self, cmd, port, elevated=False, wait_echo=True):
        super().send_command(cmd, port, elevated, wait_echo)

    @notify_error
    def take_snapshot(self, port, timeout=180):
        return super().take_snapshot(port, timeout)

    @notify_error
    def collect_rmod_output(self, port):
        return super().collect_rmod_output(port)

    @notify_error
    def get_session_log_path(self, port):
        return str(PurePosixPath(super().get_session_log_path(port)))

    @notify_error
    def get_rmod_info(self, port):
        return super().get_rmod_info(port)

    @notify_error
    def set_rmod_credentials(self, port, login, password, shell_prompt_regex=None):
        super().set_rmod_credentials(port, login, password, shell_prompt_regex)
